// The "Open" example (the second preview): every card pinned open through shown, the pointer ignored.
const open = document.querySelectorAll(".showcase .preview")[1];
const els = [...open.querySelectorAll("acme-relative-time")];
for (const el of els) { el.disableTriggers = true; el.shown = 1; }
return Promise.all(els.map(async (el) => { await el.updateComplete; await el.shadowRoot.querySelector("acme-context-card")?.updateComplete; })).then(() => {
  // Ours slots the card's content in whether the card is open or shut; the reference builds that
  // content only when the card opens. So a closed card would contribute a root the reference does
  // not have, and the diff pairs roots by order — our side read 6 against the reference's 4 and every
  // comparison shifted. Drop the content of every card that is not open, leaving the four pinned above.
  // A hop selector cannot express this: the content is slotted INTO the card, never inside it.
  for (const el of document.querySelectorAll("acme-relative-time")) {
    const card = el.shadowRoot?.querySelector("acme-context-card");
    if (!card?.shadowRoot?.querySelector(".layer")) el.shadowRoot?.querySelector(".content")?.remove();
  }
});

// The label is the short age our element draws when NOTHING is slotted — the "Plain" example, the
// third preview. The other five cards slot a button, so their `.time` node is the button's label
// rather than the fallback, and the reference has no counterpart for it: the reference page shows
// one plain label. Reading all six made our side report 6 roots against the reference's 1, and the
// diff pairs roots by order, so every comparison shifted. Drop the label of every card that has
// something slotted.
for (const el of document.querySelectorAll("acme-relative-time")) {
  if (el.children.length > 0) el.shadowRoot?.querySelector(".time")?.remove();
}
